   evidence=dict(trial='CALGB 40603 (Alliance)',population='Stage II–III TNBC; 443 treated participants.',comparison='Carboplatin allocation versus no carboplatin, pooled across the factorial bevacizumab allocation.',applicability='The planned AUC6 every-three-week platinum / weekly paclitaxel → dose-dense AC backbone matches 00348. The factorial design limits a simple regimen-to-regimen interpretation.',endpoints=outcomes,harms='Carboplatin increased haematological toxicity and missed or reduced doses.',sources=refs)
